const log = debug("werift-ice:packages/ice/src/turn/protocol.ts");

const DEFAULT_CHANNEL_REFRESH_TIME = 500;
const DEFAULT_ALLOCATION_LIFETIME = 600;
const UDP_TRANSPORT = 0x11000000;
/** 300 (Try Alternate) redirects followed for one Allocate before giving up. */
const DEFAULT_MAX_ALLOCATE_REDIRECTS = 3;

export {
  TurnRedirectError,
  type TurnRedirectFailureReason,
} from "../exceptions";

/**
 * Opens a new stream transport to the TURN server named by a 300 (Try
 * Alternate) ALTERNATE-SERVER. `alternateDomain` is the ALTERNATE-DOMAIN
 * attribute, if any, which a TLS transport must validate the certificate
 * against (RFC 8489 §10).
 */
export type TurnStreamReconnect = (
  server: Address,
  alternateDomain: string | undefined,
) => Promise<Transport>;

/** Where a 300 (Try Alternate) response tells the client to go. */
interface TurnAlternate {
  server: Address;
  domain?: string;
}

/** Channel binding state for a single peer transport address. */
export interface TurnChannel {
  number: number;
  address: Address;
  /** Unix seconds when this channel should be refreshed. */
  refreshAt: number;
}

function isStreamTransport(transport: Transport) {
  return transport.type === "tcp" || transport.type === "tls";
}

/** Permission is peer-IP scoped (RFC 8656). */
function permissionKey(addr: Address): string {
  return addr[0];
}

/** ChannelBind is peer transport-address scoped (IP + port). */
function channelKey(addr: Address): string {
  return JSON.stringify(addr);
}

export class StunOverTurnProtocol implements Protocol {
  public turn: TurnProtocol;
  /**
   * The transport the TURN server was configured with. A UDP entry whose
   * allocation fell back to TCP keeps "udp" here, so a restart that removes
   * that entry also releases the fallback allocation.
   */
  configuredTransport?: "udp" | "tcp" | "tls";

  static type = "turn";
  readonly type = StunOverTurnProtocol.type;
  localCandidate!: Candidate;
  private disposer = new EventDisposer();
  onRequestReceived: Event<[Message, Address, Buffer]> = new Event();
  onDataReceived: Event<[Buffer]> = new Event();

  constructor(turn: TurnProtocol) {
    this.turn = turn;
    turn.onData
      .subscribe((data, addr) => {
        this.handleStunMessage(data, addr);
      })
      .disposer(this.disposer);
  }

  private handleStunMessage = (data: Buffer, addr: Address) => {
    try {
      const message = parseMessage(data);
      if (!message) {
        this.onDataReceived.execute(data);
        return;
      }

      if (
        message.messageClass === classes.RESPONSE ||
        message.messageClass === classes.ERROR
      ) {
        const transaction = this.turn.transactions[message.transactionIdHex];
        if (transaction) {
          const verified = transaction.integrityKey
            ? parseMessage(data, transaction.integrityKey)
            : message;
          if (!verified) {
            log("STUN over TURN response failed MESSAGE-INTEGRITY check");
            return;
          }
          transaction.responseReceived(verified, addr);
        }
      } else if (message.messageClass === classes.REQUEST) {
        this.onRequestReceived.execute(message, addr, data);
      }
    } catch (error) {
      log("datagramReceived error", error);
    }
  };

  async request(
    request: Message,
    addr: Address,
    integrityKey?: Buffer,
    retransmissionsOrOptions?: number | TransactionRequestOptions,
    onRequestSent?: (attempt: number) => void,
  ) {
    if (this.turn.transactions[request.transactionIdHex]) {
      throw new Error("exist");
    }

    if (integrityKey) {
      request.addMessageIntegrity(integrityKey);
      request.addFingerprint();
    }

    // Peer-facing STUN over TURN must honor retransmissions/responseTimeout
    // (consent uses retransmissions: 0). Do not confuse with TURN server
    // allocation/refresh policy on TurnProtocol.
    // Peer addresses are already IPs from candidates; resolve for safety.
    const resolvedAddr = await resolveRequestAddress(addr);
    const options = buildTransactionOptions(
      integrityKey,
      retransmissionsOrOptions,
      onRequestSent,
    );
    const transaction = new Transaction(request, resolvedAddr, this, options);
    this.turn.transactions[request.transactionIdHex] = transaction;

    try {
      return await transaction.run();
    } catch (e) {
      throw e;
    } finally {
      delete this.turn.transactions[request.transactionIdHex];
    }
  }
  async connectionMade() {}
  async sendData(data: Buffer, addr: Address) {
    await this.turn.sendData(data, addr);
  }
  async sendStun(message: Message, addr: Address) {
    await this.turn.sendData(message.bytes, addr);
  }
  async close() {
    this.disposer.dispose();
    return this.turn.close();
  }
}

export class TurnProtocol implements Protocol {
  /**
   * TURN server the allocation is made on; the host may be a hostname.
   * Starts as the configured server and becomes the ALTERNATE-SERVER when
   * an Allocate is redirected with 300 (Try Alternate).
   */
  public server: Address;
  public username: string;
  public password: string;
  public lifetime: number;
  public transport: Transport;
  public options: {
    /**sec */
    channelRefreshTime?: number;
    /**
     * 300 (Try Alternate) redirects followed for one Allocate.
     * Defaults to 3.
     */
    maxAllocateRedirects?: number;
    /**
     * Reconnects a TCP/TLS transport to an ALTERNATE-SERVER. Without it, a
     * redirect over a stream transport fails with TurnRedirectError
     * ("unsupported-transport"). UDP needs no reconnect.
     */
    reconnect?: TurnStreamReconnect;
  };

  static type = "turn";
  readonly type = TurnProtocol.type;
  readonly onData = new Event<[Buffer, Address]>();
  onRequestReceived: Event<[Message, Address, Buffer]> = new Event();
  onDataReceived: Event<[Buffer]> = new Event();
  integrityKey?: Buffer;
  nonce?: Buffer;
  realm?: string;
  relayedAddress!: Address;
  mappedAddress!: Address;
  localCandidate!: Candidate;
  transactions: { [hexId: string]: Transaction } = {};
  /** close() ran: no new transaction starts. */
  private closed = false;
  private refreshHandle?: Cancelable<void>;
  private channelNumber = 0x4000;
  private channelByAddr: { [key: string]: TurnChannel } = {};
  private addrByChannel: { [channel: number]: Address } = {};
  /**sec */
  private channelRefreshTime: number;
  /**
   * Serializes ChannelBind requests so allocation-wide auth state
   * (nonce/realm/integrityKey) is not updated concurrently. Rejections
   * must not poison this tail — see channelBindQueue assignment sites.
   */
  private channelBindQueue: Promise<void> = Promise.resolve();
  /** In-flight ChannelBind per peer transport address (dedupe concurrent). */
  private channelBindingByAddr = new Map<string, Promise<TurnChannel>>();
  private tcpBuffer: Buffer = Buffer.alloc(0);
  /** Permission cache keyed by peer IP only (RFC 8656). */
  private permissionByAddr: { [peerIp: string]: boolean } = {};
  /**
   * Serializes CreatePermission requests (auth state race avoidance).
   * Rejections must not poison this tail.
   */
  private permissionQueue: Promise<void> = Promise.resolve();
  /** In-flight CreatePermission per peer IP (dedupe concurrent). */
  private creatingPermissionByAddr = new Map<string, Promise<void>>();
  /** Concrete TURN server address the allocation lives on, once selected. */
  private pinnedServerEndpoint?: Address;
  private serverEndpointSelection?: Promise<Address>;

  /** TURN server as configured, before any 300 (Try Alternate) redirect. */
  readonly configuredServer: Address;

  constructor(
    server: Address,
    username: string,
    password: string,
    lifetime: number,
    transport: Transport,
    options: {
      /**sec */
      channelRefreshTime?: number;
      /**
       * 300 (Try Alternate) redirects followed for one Allocate.
       * Defaults to 3.
       */
      maxAllocateRedirects?: number;
      /**
       * Reconnects a TCP/TLS transport to an ALTERNATE-SERVER. Without it, a
       * redirect over a stream transport fails with TurnRedirectError
       * ("unsupported-transport"). UDP needs no reconnect.
       */
      reconnect?: TurnStreamReconnect;
    } = {},
  ) {
    this.server = server;
    this.username = username;
    this.password = password;
    this.lifetime = lifetime;
    this.transport = transport;
    this.options = options;
    this.configuredServer = server;
    this.channelRefreshTime =
      this.options.channelRefreshTime ?? DEFAULT_CHANNEL_REFRESH_TIME;
  }

  async connectionMade() {
    this.attachTransport();

    const [response] = await this.allocate().catch((e) => {
      log("connect error", e);
      throw e;
    });
    this.relayedAddress = response.getAttributeValue("XOR-RELAYED-ADDRESS");
    this.mappedAddress = response.getAttributeValue("XOR-MAPPED-ADDRESS");
    const exp = response.getAttributeValue("LIFETIME");
    log("connect", this.relayedAddress, this.mappedAddress, { exp });

    // close() ran while the response was in flight: no refresh starts.
    if (this.closed) throw new TransactionCancelled();
    this.refresh(exp);
  }

  private attachTransport() {
    this.transport.onData = (data, addr) => {
      this.dataReceived(data, addr);
    };
    this.transport.onError?.subscribe((error) => {
      log("transport error", error);
    });
  }

  /**
   * Allocate on the current server, following 300 (Try Alternate) to the
   * ALTERNATE-SERVER with the same transport protocol and credentials
   * (RFC 8656 §7.4, RFC 8489 §10). Only Allocate is redirected: an existing
   * allocation lives on one server, so Refresh, CreatePermission and
   * ChannelBind never move.
   */
  private async allocate(): Promise<[Message, Address]> {
    const maxRedirects =
      this.options.maxAllocateRedirects ?? DEFAULT_MAX_ALLOCATE_REDIRECTS;
    /** Servers this Allocate has been sent to, to detect redirect loops. */
    const tried: Address[] = [];

    for (let redirects = 0; ; redirects++) {
      // A fresh request per server: a redirected request may already carry
      // MESSAGE-INTEGRITY for the previous server's realm and nonce.
      const request = new Message(methods.ALLOCATE, classes.REQUEST)
        .setAttribute("LIFETIME", this.lifetime)
        .setAttribute("REQUESTED-TRANSPORT", UDP_TRANSPORT);

      try {
        return await this.requestWithRetry(request, this.server);
      } catch (error) {
        const alternate = tryAlternateOf(error, this.transport.addressFamily);
        if (!alternate) {
          throw error;
        }
        // The request has resolved the configured host, so its endpoint is
        // known here: a redirect to the resolved IP of a host name is a loop.
        tried.push(this.server);
        if (this.pinnedServerEndpoint) {
          tried.push(this.pinnedServerEndpoint);
        }
        const failed = error as TransactionFailed;
        const fail = (
          reason: ConstructorParameters<typeof TurnRedirectError>[0],
        ) =>
          new TurnRedirectError(reason, this.server, alternate.server, failed);

        if (!alternate.server) {
          throw new TurnRedirectError(
            "missing-alternate",
            this.server,
            undefined,
            failed,
          );
        }
        if (tried.some((addr) => addressEquals(addr, alternate.server!))) {
          throw fail("loop");
        }
        if (redirects >= maxRedirects) {
          throw fail("too-many-redirects");
        }
        if (isStreamTransport(this.transport) && !this.options.reconnect) {
          throw fail("unsupported-transport");
        }

        log("allocate redirected", this.server, "->", alternate);
        await this.switchServer(alternate as TurnAlternate);
      }
    }
  }

  /**
   * Point the client at an ALTERNATE-SERVER. Authentication state belongs to
   * the previous server, so the alternate starts again with an
   * unauthenticated Allocate and its own 401 realm/nonce; username and
   * password are kept.
   */
  private async switchServer({ server, domain }: TurnAlternate) {
    let endpoint: Address;
    if (isStreamTransport(this.transport)) {
      const previous = this.transport;
      previous.onData = () => {};
      await previous.close();
      const reconnected = await this.options.reconnect!(server, domain);
      // close() ran while reconnecting: it saw only the closed previous
      // transport, so the new connection is released here.
      if (this.closed) {
        reconnected.onData = () => {};
        await reconnected.close();
        throw new TransactionCancelled();
      }
      this.transport = reconnected;
      this.tcpBuffer = Buffer.alloc(0);
      this.attachTransport();
      endpoint = this.transport.remoteAddress ?? server;
    } else {
      // ALTERNATE-SERVER is an IP literal. One of the other family cannot be
      // reached from this socket (AddressFamilyMismatch).
      endpoint = await resolveRequestAddress(
        server,
        this.transport.addressFamily ?? 0,
      );
    }

    this.server = server;
    this.pinnedServerEndpoint = endpoint;
    this.serverEndpointSelection = Promise.resolve(endpoint);
    this.nonce = undefined;
    this.realm = undefined;
    this.integrityKey = undefined;
  }

  private handleChannelData(data: Buffer) {
    const decoded = decodeChannelData(data);
    const addr = decoded && this.addrByChannel[decoded.channelNumber];

    if (addr && decoded) {
      this.onData.execute(decoded.data, addr);
    }
  }

  private handleSTUNMessage(data: Buffer, addr: Address) {
    try {
      const message = parseMessage(data);
      if (!message) {
        throw new Error("not stun message");
      }

      if (
        message.messageClass === classes.RESPONSE ||
        message.messageClass === classes.ERROR
      ) {
        const transaction = this.transactions[message.transactionIdHex];
        if (transaction) {
          this.handleResponse(transaction, message, data, addr);
        }
      } else if (message.messageClass === classes.REQUEST) {
        this.onData.execute(data, addr);
      }

      if (message.getAttributeValue("DATA")) {
        const buf: Buffer = message.getAttributeValue("DATA");
        const peerAddress =
          message.getAttributeValue("XOR-PEER-ADDRESS") ?? addr;
        this.onData.execute(buf, peerAddress);
      }
    } catch (error) {
      log("parse error", data.toString());
    }
  }

  /**
   * Long-term credentials (RFC 8489 §9.2.5): a response to an authenticated
   * request must carry a valid MESSAGE-INTEGRITY, except a 401/438 challenge
   * without one, which goes to the retry logic of requestWithRetry. Over
   * UDP an unverified response is dropped and retransmissions continue; over
   * TCP/TLS it ends the transaction, except an unsigned 400, which is
   * discarded as if never received.
   */
  private handleResponse(
    transaction: Transaction,
    message: Message,
    data: Buffer,
    addr: Address,
  ) {
    if (!transaction.integrityKey) {
      transaction.responseReceived(message, addr);
      return;
    }
    if (isUnauthenticatedChallenge(message)) {
      transaction.challengeReceived(message, addr);
      return;
    }
    const verified = parseMessage(data, transaction.integrityKey);
    if (verified) {
      transaction.responseReceived(verified, addr);
      return;
    }
    log("TURN STUN response failed MESSAGE-INTEGRITY check");
    const [errorCode] = message.getAttributeValue("ERROR-CODE") ?? [];
    const unsignedBadRequest =
      message.messageClass === classes.ERROR &&
      errorCode === 400 &&
      !hasMessageIntegrity(message);
    if (isStreamTransport(this.transport) && !unsignedBadRequest) {
      transaction.integrityViolated(addr);
    }
  }

  private dataReceived(data: Buffer, addr: Address) {
    const datagramReceived = (data: Buffer, addr: Address) => {
      if (data.length >= 4 && isChannelData(data)) {
        this.handleChannelData(data);
      } else {
        this.handleSTUNMessage(data, addr);
      }
    };

    if (isStreamTransport(this.transport)) {
      this.tcpBuffer = Buffer.concat([this.tcpBuffer, data]);
      const { frames, rest } = splitTurnTcpFrames(this.tcpBuffer);
      this.tcpBuffer = rest;
      for (const frame of frames) {
        datagramReceived(frame, addr);
      }
    } else {
      datagramReceived(data, addr);
    }
  }

  private async send(data: Buffer, addr: Address) {
    if (this.transport.closed) {
      return;
    }

    await this.transport.send(
      isStreamTransport(this.transport) ? padTurnFrame(data) : data,
      addr,
    );
  }

  private async createPermission(peerAddress: Address) {
    const request = new Message(methods.CREATE_PERMISSION, classes.REQUEST);
    request
      .setAttribute("XOR-PEER-ADDRESS", peerAddress)
      .setAttribute("USERNAME", this.username)
      .setAttribute("REALM", this.realm)
      .setAttribute("NONCE", this.nonce);
    // Use requestWithRetry for stale-nonce (438) consistency with ChannelBind.
    await this.requestWithRetry(request, this.server);
  }

  private refresh = (exp: number) => {
    this.refreshHandle = cancelable<void>(async (_, __, onCancel) => {
      const abort = new AbortController();
      onCancel.once(() => {
        abort.abort();
      });

      while (!abort.signal.aborted) {
        // refresh before expire
        const delay = (5 / 6) * exp * 1000;
        log("refresh delay", delay, { exp });
        try {
          await setTimeout(delay, undefined, { signal: abort.signal });
        } catch (error) {
          if (abort.signal.aborted) {
            return;
          }
          throw error;
        }

        if (abort.signal.aborted) {
          return;
        }

        const request = new Message(methods.REFRESH, classes.REQUEST);
        request.setAttribute("LIFETIME", exp);

        try {
          const [message] = await this.requestWithRetry(
            request,
            this.server,
            abort.signal,
          );
          exp = message.getAttributeValue("LIFETIME");
          log("refresh", { exp });
        } catch (error) {
          if (abort.signal.aborted) {
            return;
          }
          log("refresh error", error);
        }
      }
    });
  };

  async request(
    request: Message,
    addr: Address,
    _integrityKey?: Buffer,
    retransmissionsOrOptions?: number | TransactionRequestOptions,
    onRequestSent?: (attempt: number) => void,
    credentials?: { realm: string; nonce: Buffer; integrityKey: Buffer },
  ): Promise<[Message, Address]> {
    if (this.transactions[request.transactionIdHex]) {
      throw new Error("exist");
    }
    const signing = credentials ?? {
      realm: this.realm,
      nonce: this.nonce,
      integrityKey: this.integrityKey,
    };
    if (signing.integrityKey) {
      // A retried request still carries the previous signature, which would
      // otherwise be covered by the new MESSAGE-INTEGRITY.
      request
        .removeAttribute("MESSAGE-INTEGRITY")
        .removeAttribute("MESSAGE-INTEGRITY-SHA256")
        .removeAttribute("FINGERPRINT")
        .setAttribute("USERNAME", this.username)
        .setAttribute("REALM", signing.realm)
        .setAttribute("NONCE", signing.nonce)
        .addMessageIntegrity(signing.integrityKey)
        .addFingerprint();
    }

    // TURN server allocation/refresh uses default STUN retry policy unless
    // callers pass explicit options. Peer consent goes through StunOverTurnProtocol.
    // Prefer the TURN session integrity key for response verification.
    const resolvedAddr = await this.resolveRequestTarget(addr);
    // close() ran during the lookup: no transaction starts on a closed client.
    if (this.closed) throw new TransactionCancelled();
    const options = buildTransactionOptions(
      signing.integrityKey,
      retransmissionsOrOptions,
      onRequestSent,
    );
    const transaction = new Transaction(request, resolvedAddr, this, options);
    this.transactions[request.transactionIdHex] = transaction;

    try {
      return await transaction.run();
    } catch (e) {
      throw e;
    } finally {
      delete this.transactions[request.transactionIdHex];
    }
  }

  /**
   * The concrete TURN server address, selected on the first request and
   * pinned for the rest of the allocation, so a later DNS answer can never
   * move REFRESH, CREATE_PERMISSION, CHANNEL_BIND or data to another server.
   */
  get serverEndpoint(): Address | undefined {
    return this.pinnedServerEndpoint;
  }

  /**
   * Address a request to `addr` is sent to, and the address its response
   * must come from. A stream carries every request to the peer it is
   * connected to, so it always uses the server endpoint.
   */
  private async resolveRequestTarget(addr: Address): Promise<Address> {
    if (isStreamTransport(this.transport) || addressEquals(addr, this.server)) {
      return this.selectServerEndpoint();
    }
    return resolveRequestAddress(addr, this.transport.addressFamily ?? 0);
  }

  private async serverDestination(): Promise<Address> {
    return this.pinnedServerEndpoint ?? this.selectServerEndpoint();
  }

  private selectServerEndpoint(): Promise<Address> {
    this.serverEndpointSelection ??= this.resolveServerEndpoint().then(
      (endpoint) => {
        this.pinnedServerEndpoint = endpoint;
        return endpoint;
      },
      (error) => {
        // Let a later request try again, e.g. after a transient DNS failure.
        this.serverEndpointSelection = undefined;
        throw error;
      },
    );
    return this.serverEndpointSelection;
  }

  /**
   * UDP: resolve the configured server in the bound socket's family; a udp4
   * socket cannot send to an IPv6 answer. TCP/TLS: use the peer the socket
   * actually connected to. Looking the hostname up again could return a
   * different A/AAAA record, and responses from the real peer would then be
   * dropped as coming from an unexpected address.
   */
  private async resolveServerEndpoint(): Promise<Address> {
    const transport = this.transport;
    if (!isStreamTransport(transport)) {
      return resolveRequestAddress(this.server, transport.addressFamily ?? 0);
    }
    if (transport.remoteAddress) {
      return transport.remoteAddress;
    }
    if (
      transport instanceof TcpTransport ||
      transport instanceof TlsTransport
    ) {
      throw new Error(`${transport.type} transport has no remote address`);
    }
    // A custom stream transport that does not report its peer: fall back to
    // a lookup with no family preference.
    return resolveRequestAddress(this.server);
  }

  /**
   * Send a request and follow the long-term credential mechanism of
   * RFC 8489 §9.2.5: a 401 (Unauthenticated) or 438 (Stale Nonce) that
   * allows it (see credentialRetryOf) is retried once with the new realm and
   * nonce; any other error, or a second challenge, is thrown. The allocation's
   * realm, nonce and integrity key change only when a retry is made; a retry
   * under a new realm adopts them only once the server accepted it.
   */
  async requestWithRetry(
    request: Message,
    addr: Address,
    signal?: AbortSignal,
  ): Promise<[Message, Address]> {
    try {
      return await this.request(request, addr, undefined, { signal });
    } catch (error) {
      if (error instanceof TransactionFailed == false) {
        log("requestWithRetry error", error);
        throw error;
      }

      // request() signed the request with the credentials of that moment.
      const authenticated =
        request.attributesKeys.includes("MESSAGE-INTEGRITY");
      const sentRealm: string | undefined = authenticated
        ? request.getAttributeValue("REALM")
        : undefined;
      const retry = credentialRetryOf(
        error.response,
        { authenticated, realm: sentRealm },
        this.realm,
      );
      if (!retry) {
        throw error;
      }
      log("retry with nonce", error.str, {
        signedError: !(error instanceof TransactionChallenge),
      });

      const integrityKey = makeIntegrityKey(
        this.username,
        retry.realm,
        this.password,
      );
      request.transactionId = randomTransactionId();

      // A new realm on an authenticated request rekeys the whole allocation.
      // Sign the retry with its own credentials and adopt them only once the
      // server accepted it, so concurrent failures never overwrite the shared
      // state with credentials that were rejected.
      if (authenticated && retry.realm !== sentRealm) {
        const credentials = {
          realm: retry.realm,
          nonce: retry.nonce,
          integrityKey,
        };
        const result = await this.request(
          request,
          this.server,
          undefined,
          { signal },
          undefined,
          credentials,
        );
        this.nonce = credentials.nonce;
        this.realm = credentials.realm;
        this.integrityKey = credentials.integrityKey;
        return result;
      }

      this.nonce = retry.nonce;
      this.realm = retry.realm;
      this.integrityKey = integrityKey;
      return await this.request(request, this.server, undefined, { signal });
    }
  }

  async sendData(data: Buffer, addr: Address) {
    let channel: TurnChannel | undefined;
    try {
      channel = await this.getChannel(addr);
    } catch (e) {
      // Keep original ChannelBind error for diagnostics (403/438/timeout).
      log("channelBind error; falling back to Send Indication", e);
    }

    if (!channel) {
      await this.getPermission(addr);
      const indicate = new Message(methods.SEND, classes.INDICATION)
        .setAttribute("DATA", data)
        .setAttribute("XOR-PEER-ADDRESS", addr);

      await this.sendStun(indicate, await this.serverDestination());
      return;
    }

    await this.send(
      encodeChannelData(channel.number, data),
      await this.serverDestination(),
    );
  }

  /**
   * Ensure a CreatePermission exists for the peer IP.
   * Peer failures are isolated: a rejection for peer A does not poison peer B.
   */
  async getPermission(addr: Address) {
    const key = permissionKey(addr);

    if (this.permissionByAddr[key]) {
      return;
    }

    const existing = this.creatingPermissionByAddr.get(key);
    if (existing) {
      return existing;
    }

    const operation = this.permissionQueue.then(async () => {
      // Another caller may have succeeded while we waited on the queue.
      if (this.permissionByAddr[key]) {
        return;
      }

      await this.createPermission(addr);
      // Cache only after successful CreatePermission.
      this.permissionByAddr[key] = true;
    });

    // Do not let rejection poison subsequent peers on the shared queue.
    this.permissionQueue = operation.then(
      () => undefined,
      () => undefined,
    );

    this.creatingPermissionByAddr.set(key, operation);

    try {
      await operation;
    } catch (error) {
      log("createPermission error", error);
      throw error;
    } finally {
      if (this.creatingPermissionByAddr.get(key) === operation) {
        this.creatingPermissionByAddr.delete(key);
      }
    }
  }

  /**
   * Ensure a ChannelBind exists for the peer transport address.
   * Peer failures are isolated; concurrent same-peer calls share one Promise.
   */
  async getChannel(addr: Address): Promise<TurnChannel> {
    const key = channelKey(addr);

    const existing = this.channelBindingByAddr.get(key);
    if (existing) {
      return existing;
    }

    // Fast path: bound and not due for refresh.
    const cached = this.channelByAddr[key];
    const now = int(Date.now() / 1000);
    if (cached && cached.refreshAt > now) {
      return cached;
    }

    const operation = this.channelBindQueue.then(() =>
      this.ensureChannel(addr),
    );

    // Do not let rejection poison subsequent peers on the shared queue.
    this.channelBindQueue = operation.then(
      () => undefined,
      () => undefined,
    );

    this.channelBindingByAddr.set(key, operation);

    try {
      return await operation;
    } catch (error) {
      log("channelBind error", error);
      throw error;
    } finally {
      if (this.channelBindingByAddr.get(key) === operation) {
        this.channelBindingByAddr.delete(key);
      }
    }
  }

  /**
   * Create or refresh a channel for addr. Provisional mapping is installed
   * before the request so early ChannelData can be decoded; only a failed
   * *initial* bind rolls the mapping back. Failed channel numbers are never
   * reused.
   */
  private async ensureChannel(addr: Address): Promise<TurnChannel> {
    const key = channelKey(addr);
    const now = int(Date.now() / 1000);

    let channel = this.channelByAddr[key];
    if (channel && channel.refreshAt > now) {
      return channel;
    }

    const isNew = !channel;

    if (!channel) {
      channel = {
        number: this.channelNumber++,
        address: addr,
        refreshAt: 0,
      };
      // Provisional mapping for ChannelData that may arrive before success.
      this.channelByAddr[key] = channel;
      this.addrByChannel[channel.number] = addr;
    }

    try {
      await this.channelBind(channel.number, addr);
      channel.refreshAt = int(Date.now() / 1000) + this.channelRefreshTime;
      log(isNew ? "channelBind" : "channelBind refresh", channel);
      return channel;
    } catch (error) {
      if (isNew) {
        // Roll back provisional mapping only for a failed initial bind.
        delete this.channelByAddr[key];
        delete this.addrByChannel[channel.number];
        // Do not reuse the channel number (no channelNumber--).
      }
      throw error;
    }
  }

  private async channelBind(channelNumber: number, addr: Address) {
    const request = new Message(methods.CHANNEL_BIND, classes.REQUEST);
    request
      .setAttribute("CHANNEL-NUMBER", channelNumber)
      .setAttribute("XOR-PEER-ADDRESS", addr);
    const [response] = await this.requestWithRetry(request, this.server);
    if (response.messageMethod !== methods.CHANNEL_BIND) {
      throw new Error("should be CHANNEL_BIND");
    }
  }

  async sendStun(message: Message, addr: Address) {
    await this.send(message.bytes, addr);
  }

  /**
   * Release the client: its transactions, refresh timer and socket. Known
   * constraint (as in develop): the allocation is not deleted on the server
   * (no Refresh with lifetime 0), so the server keeps it until its lifetime
   * ends.
   */
  async close() {
    if (this.closed) return;
    this.closed = true;
    // An allocation, refresh or ChannelBind still waiting settles now.
    for (const transaction of Object.values(this.transactions)) {
      transaction.cancel();
    }
    this.refreshHandle?.resolve?.();
    await this.transport.close();
  }
}

export interface TurnClientConfig {
  address: Address;
  username: string;
  password: string;
}
export interface TurnClientOptions {
  lifetime?: number;
  ssl?: boolean;
  transport?: "udp" | "tcp" | "tls";
  tlsOptions?: TlsConnectionOptions;
  portRange?: [number, number];
  interfaceAddresses?: InterfaceAddresses;
  /** Maximum time to wait for TCP/TLS connection establishment, in milliseconds. */
  connectTimeoutMs?: number;
  /**
   * Preferred IP family of the UDP socket, applied only when the server
   * address is a hostname. Ignored for an IP literal server address, whose
   * own family always selects the socket. Defaults to 4.
   */
  udpFamily?: 4 | 6;
  /**
   * Aborting it while the allocation runs closes the client (its socket and
   * transactions) and rejects with `TransactionCancelled`.
   */
  signal?: AbortSignal;
}

/**
 * Select the UDP socket type for a TURN server.
 * Precedence: IP literal family > udpFamily > 4.
 * An IP literal fixes the destination family, so a conflicting udpFamily is
 * ignored (and logged) rather than making the server unreachable.
 */
function selectTurnUdpSocketType(
  address: Address,
  udpFamily: 4 | 6 | undefined,
): "udp4" | "udp6" {
  const literalFamily = isIP(address[0]);
  if (literalFamily === 4 || literalFamily === 6) {
    if (udpFamily && udpFamily !== literalFamily) {
      log("udpFamily ignored for IP literal TURN server", {
        address,
        udpFamily,
        literalFamily,
      });
    }
    return literalFamily === 6 ? "udp6" : "udp4";
  }
  return (udpFamily ?? 4) === 6 ? "udp6" : "udp4";
}

export async function createTurnClient(
  { address, username, password }: TurnClientConfig,
  {
    lifetime,
    portRange,
    interfaceAddresses,
    ssl,
    tlsOptions,
    transport: transportType,
    connectTimeoutMs,
    udpFamily,
    signal,
  }: TurnClientOptions = {},
) {
  lifetime ??= DEFAULT_ALLOCATION_LIFETIME;
  transportType ??= ssl ? "tls" : "udp";
  const transport =
    transportType === "udp"
      ? await UdpTransport.init(selectTurnUdpSocketType(address, udpFamily), {
          portRange,
          interfaceAddresses,
        })
      : transportType === "tcp"
        ? await TcpTransport.init(address, { connectTimeoutMs })
        : await TlsTransport.init(address, tlsOptions, { connectTimeoutMs });

  const turn = new TurnProtocol(
    address,
    username,
    password,
    lifetime,
    transport,
    {
      reconnect:
        transportType === "udp"
          ? undefined
          : (alternate, alternateDomain) =>
              transportType === "tcp"
                ? TcpTransport.init(alternate, { connectTimeoutMs })
                : TlsTransport.init(
                    alternate,
                    alternateTlsOptions(address, alternateDomain, tlsOptions),
                    { connectTimeoutMs },
                  ),
    },
  );
  // The owner (an ICE agent) closed while the allocation runs: release the
  // socket and its retransmissions now instead of after the allocation.
  const abort = () => {
    turn
      .close()
      .catch((error) => log("failed to close aborted TURN client", error));
  };
  if (signal?.aborted) abort();
  signal?.addEventListener("abort", abort, { once: true });

  try {
    if (signal?.aborted) throw new TransactionCancelled();
    await turn.connectionMade();
    if (signal?.aborted) throw new TransactionCancelled();
  } catch (error) {
    try {
      await turn.close();
    } catch (closeError) {
      log("failed to close TURN client after allocation failure", closeError);
    }
    throw error;
  } finally {
    signal?.removeEventListener("abort", abort);
  }
  return turn;
}

export async function createStunOverTurnClient(
  config: TurnClientConfig,
  options: TurnClientOptions = {},
) {
  const turn = await createTurnClient(config, options);
  const turnTransport = new StunOverTurnProtocol(turn);
  return turnTransport;
}

/**
 * TLS options for a connection to an ALTERNATE-SERVER (an IP literal). The
 * certificate is validated against ALTERNATE-DOMAIN when present, otherwise
 * against the name the original server would have been validated with
 * (RFC 8489 §10): `tlsOptions.servername`, else the configured host.
 */
function alternateTlsOptions(
  configured: Address,
  alternateDomain: string | undefined,
  tlsOptions: TlsConnectionOptions = {},
): TlsConnectionOptions {
  const identity = alternateDomain ?? tlsOptions.servername ?? configured[0];
  const checkServerIdentity =
    tlsOptions.checkServerIdentity ?? tls.checkServerIdentity;
  return {
    ...tlsOptions,
    // SNI cannot carry an IP literal.
    servername: isIP(identity) ? undefined : identity,
    checkServerIdentity: (_host, cert) => checkServerIdentity(identity, cert),
  };
}

/**
 * The redirect target of a 300 (Try Alternate) error response, or undefined
 * for any other error. `server` is undefined when ALTERNATE-SERVER is
 * missing.
 */
function tryAlternateOf(
  error: unknown,
  addressFamily?: number,
): { server?: Address; domain?: string } | undefined {
  if (!(error instanceof TransactionFailed)) {
    return undefined;
  }
  const [errorCode] = error.response.getAttributeValue("ERROR-CODE") ?? [];
  if (errorCode !== 300) {
    return undefined;
  }
  // A response may carry one ALTERNATE-SERVER per address family (RFC 8489
  // §10): take the first one this transport can reach, else the first.
  const servers = error.response.alternateServers;
  const reachable = servers.find(
    ([host]) => addressFamily === undefined || ipFamily(host) === addressFamily,
  );
  return {
    server: reachable ?? servers[0],
    domain: error.response.getAttributeValue("ALTERNATE-DOMAIN"),
  };
}

function ipFamily(host: string): number {
  return host.includes(":") ? 6 : 4;
}

export function makeIntegrityKey(
  username: string,
  realm: string,
  password: string,
) {
  return makeTurnIntegrityKey(username, realm, password);
}
